# Feature index expressions: all affine linear mod 3 over i,j,u,v with coefficients -1,0,1 and const 0..2
exprs=[]
for co in itertools.product(range(3), repeat=4):
    if not any(co): continue
    for c in range(3): exprs.append((co,c))
def val_expr(expr, x): return (sum(a*b for a,b in zip(expr[0],x))+expr[1])%3
# test B = not A[rowexpr,colexpr] for each pair affine expressions
samples=[]
for A,B in zip(As,outs):
  for i,j in zip(*np.where(A)):
   for u in range(3):
    for v in range(3): samples.append((A,B,i,j,u,v))

def test_pair(e1,e2):
  return all(B[i,j,u,v] == 1-A[val_expr(e1,(i,j,u,v)),val_expr(e2,(i,j,u,v))] for A,B,i,j,u,v in samples)
