# feature candidates of A at index pairs made from i,j,u,v, and center constants
terms=[]
vars_names=['i','j','u','v']
for x in vars_names+['0','1','2']:
 for y in vars_names+['0','1','2']:
  def idxfun(z,x=x): return z[vars_names.index(x)] if x in vars_names else int(x)
  def make_term(x,y):
   return (f'A[{x},{y}]', lambda A,z,x=x,y=y: int(A[(z[vars_names.index(x)] if x in vars_names else int(x)),(z[vars_names.index(y)] if y in vars_names else int(y))]))
  terms.append(make_term(x,y))
# unique feature vectors and check consistency for combos
featvals=np.array([[fn(A,(i,j,u,v)) for _,fn in terms] for A,B,i,j,u,v in samples])
labels=np.array([B[i,j,u,v] for A,B,i,j,u,v in samples])
